#include <bits/stdc++.h>
using namespace std;

constexpr int MAXN = 2002;
constexpr int INF = 1000;

int cap[MAXN][MAXN];
vector<int> adj[MAXN];
bool visited[MAXN];
int par[MAXN];

int dirs[4][2] = {{1,0}, {0,1}, {-1,0}, {0,-1}};

int dfs(int u, int sink, int flow) {
    if (u == sink) return flow;
    visited[u] = true;
    for (int v : adj[u]) {
        if (!visited[v] && cap[u][v] > 0) {
            int f = dfs(v, sink, min(flow, cap[u][v]));
            if (f > 0) {
                par[v] = u;
                return f;
            }
        }
    }
    return 0;
}

int max_flow(int src, int sink, int nodes) {
    int total = 0;
    while (true) {
        fill(visited, visited + nodes, false);
        fill(par, par + nodes, -1);
        int f = dfs(src, sink, INF);
        if (f == 0) break;
        total += f;
        for (int v = sink; v != src; v = par[v]) {
            int u = par[v];
            cap[u][v] -= f;
            cap[v][u] += f;
        }
    }
    return total;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int dim, time_limit;
    cin >> dim >> time_limit;

    int nodes = 2 * dim * dim + 2;
    for (int i = 0; i < nodes; ++i) {
        adj[i].clear();
        for (int j = 0; j < nodes; ++j)
            cap[i][j] = 0;
    }

    vector<string> sci(dim), cap_str(dim);
    int vert[dim][dim][2];
    int bad_cell = -1;

    int next_node = 2;
    for (int i = 0; i < dim; ++i) {
        cin >> sci[i];
        for (int j = 0; j < dim; ++j) {
            char c = sci[i][j];
            if (c >= '1' && c <= '9') {
                int node = next_node++;
                cap[0][node] = c - '0';
                adj[0].push_back(node);
                adj[node].push_back(0);
                vert[i][j][0] = node;
            } else if (c == 'Z') {
                bad_cell = 100 * i + j;
                sci[i][j] = 'Y';
            }
        }
    }

    int max_node = next_node;
    for (int i = 0; i < dim; ++i) {
        cin >> cap_str[i];
        for (int j = 0; j < dim; ++j) {
            char c = cap_str[i][j];
            if (c >= '1' && c <= '9') {
                int node = max_node++;
                cap[node][1] = c - '0';
                adj[node].push_back(1);
                vert[i][j][1] = node;
            }
        }
    }

    int dist_bad[dim][dim];
    for (int i = 0; i < dim; ++i)
        fill(dist_bad[i], dist_bad[i] + dim, time_limit + 1);
    if (bad_cell != -1) {
        dist_bad[bad_cell / 100][bad_cell % 100] = 0;
        queue<int> q;
        q.push(bad_cell);
        while (!q.empty()) {
            int pos = q.front(); q.pop();
            int x = pos / 100, y = pos % 100;
            for (int d = 0; d < 4; ++d) {
                int nx = x + dirs[d][0], ny = y + dirs[d][1];
                if (nx >= 0 && nx < dim && ny >= 0 && ny < dim &&
                    sci[nx][ny] != 'Y' && dist_bad[nx][ny] > dist_bad[x][y] + 1) {
                    dist_bad[nx][ny] = dist_bad[x][y] + 1;
                    q.push(100 * nx + ny);
                }
            }
        }
    }

    for (int i = 0; i < dim; ++i) {
        for (int j = 0; j < dim; ++j) {
            if (sci[i][j] >= '1' && sci[i][j] <= '9') {
                int dist_from[dim][dim];
                for (int x = 0; x < dim; ++x)
                    fill(dist_from[x], dist_from[x] + dim, time_limit + 1);
                dist_from[i][j] = 0;

                if (cap_str[i][j] >= '1' && cap_str[i][j] <= '9') {
                    int u = vert[i][j][0], v = vert[i][j][1];
                    cap[u][v] = INF;
                    adj[u].push_back(v);
                    adj[v].push_back(u);
                }

                queue<int> q;
                q.push(100 * i + j);
                while (!q.empty()) {
                    int pos = q.front(); q.pop();
                    int x = pos / 100, y = pos % 100;

                    for (int d = 0; d < 4; ++d) {
                        int nx = x + dirs[d][0], ny = y + dirs[d][1];
                        if (nx >= 0 && nx < dim && ny >= 0 && ny < dim &&
                            sci[nx][ny] != 'Y' && dist_from[nx][ny] > dist_from[x][y] + 1) {
                            if (cap_str[nx][ny] >= '1' && cap_str[nx][ny] <= '9') {
                                if (dist_from[x][y] + 1 <= dist_bad[nx][ny]) {
                                    int src_node = vert[i][j][0];
                                    int dst_node = vert[nx][ny][1];
                                    cap[src_node][dst_node] = INF;
                                    adj[src_node].push_back(dst_node);
                                    adj[dst_node].push_back(src_node);
                                }
                            }
                            if (dist_from[x][y] + 1 < dist_bad[nx][ny]) {
                                dist_from[nx][ny] = dist_from[x][y] + 1;
                                q.push(100 * nx + ny);
                            }
                        }
                    }
                }
            }
        }
    }

    cout << max_flow(0, 1, nodes) << '\n';

    return 0;
}
